    ('00000000-0000-0000-0000-000000018046', '原创题扩容'),
    ('00000000-0000-0000-0000-000000018047', '快速扩容'),
    ('00000000-0000-0000-0000-000000018047', '408资料目录'),
    ('00000000-0000-0000-0000-000000018047', '教材知识点'),
    ('00000000-0000-0000-0000-000000018047', '模拟题扩容'),
    ('00000000-0000-0000-0000-000000018048', '快速扩容'),
    ('00000000-0000-0000-0000-000000018048', '408资料目录'),
    ('00000000-0000-0000-0000-000000018048', '教材知识点'),
    ('00000000-0000-0000-0000-000000018048', '真题')
) AS relation(question_id, tag_name)
JOIN question_tags tag ON tag.name = relation.tag_name
WHERE NOT EXISTS (
    SELECT 1 FROM question_tag_relations existing
    WHERE existing.question_id = CAST(relation.question_id AS UUID)
      AND existing.tag_id = tag.id
);
